                {"itens":[{"precoUnitario":990.10,"quantidade":1,"pesoKg":1}],"modalidadeEntrega":"RETIRADA_LOJA",
                 "formaPagamento":"BOLETO","nivelClube":"BRONZE","regiao":"SUL"}""")
